    cin >> x;

    __int128 target = x;
    if (target < 0) target = -target;

    unsigned long long n = static_cast<unsigned long long>(
        ceill((sqrtl(1.0L + 8.0L * static_cast<long double>(target)) - 1.0L) / 2.0L)
    );

    __int128 sum = (__int128)n * (n + 1) / 2;

    while (sum < target || (sum - target) % 2 != 0) {
        ++n;
        sum += n;
    }

    cout << n << '\n';
    return 0;
